/**
 * <p>Appends a time zone offset in the numeric form {@code +/-HHMM}, or
 * {@code +/-HH:MM} when a colon is requested.</p>
 *
 * <p>The sign is {@code '+'} when local time is ahead of UTC and {@code '-'}
 * when it is behind. It is followed by two digits for the whole hours of the
 * offset's magnitude and two digits for its remaining minutes.</p>
 *
 * @param buffer  the buffer to append to
 * @param offsetMillis  the offset of local time from UTC in milliseconds, the sum
 *  of the {@code Calendar.ZONE_OFFSET} and {@code Calendar.DST_OFFSET} fields
 * @param colon  true to put a colon between the hours and the minutes
 * @since 3.2
 */
public static void appendZoneOffset(final StringBuffer buffer, final int offsetMillis, final boolean colon) {
    long offset = offsetMillis;
    if (offset < 0) {
        buffer.append('-');
        offset = -offset;
    } else {
        buffer.append('+');
    }

    final long offsetToHour = NumberUtils.offsetToFloorMultiple(offset, DateUtils.MILLIS_PER_HOUR);
    final int hours = DateUtils.wholeHours(offset, offsetToHour);
    buffer.append((char)(hours / 10 + '0'));
    buffer.append((char)(hours % 10 + '0'));

    if (colon) {
        buffer.append(':');
    }

    final int minutes = DateUtils.minutesPastHour(offset);
    buffer.append((char)(minutes / 10 + '0'));
    buffer.append((char)(minutes % 10 + '0'));
}

