public void testMinutesIntoTheHour() {
    assertEquals(30, DateUtils.minutesPastHour(5 * DateUtils.MILLIS_PER_HOUR + 30 * DateUtils.MILLIS_PER_MINUTE));
    assertEquals(45, DateUtils.minutesPastHour(12 * DateUtils.MILLIS_PER_HOUR + 45 * DateUtils.MILLIS_PER_MINUTE
            + 59 * DateUtils.MILLIS_PER_SECOND));
    assertEquals(0, DateUtils.minutesPastHour(3 * DateUtils.MILLIS_PER_HOUR));
    assertEquals(0, DateUtils.minutesPastHour(0));
}

@Test
public void testOffsetDownToStep() {
    assertEquals(-30L, NumberUtils.offsetToFloorMultiple(330L, 60L));
    assertEquals(0L, NumberUtils.offsetToFloorMultiple(300L, 60L));
    assertEquals(-59L, NumberUtils.offsetToFloorMultiple(359L, 60L));
    assertEquals(0L, NumberUtils.offsetToFloorMultiple(0L, 60L));
}
